'use client';

import React, { useState, useEffect } from 'react';
import {
  Utensils,
  Wifi,
  Briefcase,
  Car,
  Waves,
  Bath,
  PawPrint,
  ShieldCheck,
  ShieldAlert,
  Flame,
  X,
  Tv,
  Wind,
  Fan,
  Shirt,
  Sparkles,
  Key,
  Clock,
  Coffee,
  Microwave,
  Dumbbell,
} from 'lucide-react';
import { amenitiesPreview, amenityCategories } from '../../constants/listing-data';

interface AmenitiesSectionProps {
  onShowAll?: () => void;
}

export function AmenitiesSection({ onShowAll }: AmenitiesSectionProps) {
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  const getAmenityIcon = (name: string) => {
    switch (name.toLowerCase()) {
      case 'kitchen':
        return <Utensils size={24} className="text-[#222222]" />;
      case 'wifi':
        return <Wifi size={24} className="text-[#222222]" />;
      case 'dedicated workspace':
        return <Briefcase size={24} className="text-[#222222]" />;
      case 'free parking on premises':
        return <Car size={24} className="text-[#222222]" />;
      case 'pool':
        return <Waves size={24} className="text-[#222222]" />;
      case 'hot tub':
        return <Bath size={24} className="text-[#222222]" />;
      case 'pets allowed':
        return <PawPrint size={24} className="text-[#222222]" />;
      case 'exterior security cameras on property':
        return <ShieldCheck size={24} className="text-[#222222]" />;
      case 'carbon monoxide alarm':
        return <ShieldAlert size={24} className="text-[#717171]" />;
      case 'smoke alarm':
        return <Flame size={24} className="text-[#717171]" />;
      case 'air conditioning':
        return <Wind size={24} className="text-[#222222]" />;
      case 'ceiling fan':
        return <Fan size={24} className="text-[#222222]" />;
      case 'tv':
        return <Tv size={24} className="text-[#222222]" />;
      case 'washing machine':
      case 'hangers':
      case 'iron':
        return <Shirt size={24} className="text-[#222222]" />;
      case 'gym':
        return <Dumbbell size={24} className="text-[#222222]" />;
      case 'coffee':
        return <Coffee size={24} className="text-[#222222]" />;
      case 'microwave':
        return <Microwave size={24} className="text-[#222222]" />;
      case 'self check-in':
        return <Key size={24} className="text-[#222222]" />;
      default:
        return <Sparkles size={24} className="text-[#222222]" />;
    }
  };

  const handleOpen = () => {
    if (onShowAll) {
      onShowAll();
    } else {
      setIsOpen(true);
    }
  };

  return (
    <div id="amenities" className="py-2 font-cereal scroll-mt-28">
      <h2 className="text-[22px] font-medium text-[#222222] mb-6">
        What this place offers
      </h2>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-y-4 gap-x-12 mb-8">
        {amenitiesPreview.map((item, idx) => (
          <div key={idx} className="flex items-center gap-4">
            <div className="shrink-0">{getAmenityIcon(item.name)}</div>
            <span
              className={`text-[16px] ${
                item.unavailable ? 'line-through text-[#717171]' : 'text-[#222222]'
              }`}
            >
              {item.name}
            </span>
          </div>
        ))}
      </div>

      <button
        type="button"
        onClick={handleOpen}
        className="border border-[#222222] hover:bg-gray-100 active:scale-[0.99] text-[#222222] font-medium text-[16px] px-6 py-3.5 rounded-lg transition-all cursor-pointer focus:outline-none"
      >
        Show all 50 amenities
      </button>

      <div className="w-full h-px bg-[#DDDDDD] my-6" />

      {/* Categorized Amenities Modal */}
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-10 bg-black/50 backdrop-blur-xs">
          <div className="bg-white w-full max-w-[780px] max-h-[85vh] rounded-2xl flex flex-col shadow-2xl overflow-hidden font-cereal">
            {/* Modal Header */}
            <div className="sticky top-0 bg-white border-b border-[#EBEBEB] px-6 py-4 flex items-center justify-between z-10">
              <button
                type="button"
                onClick={() => setIsOpen(false)}
                className="w-8 h-8 rounded-full flex items-center justify-center hover:bg-gray-100 transition cursor-pointer"
              >
                <X size={20} className="text-[#222222]" />
              </button>
              <h3 className="text-[16px] font-semibold text-[#222222]">
                What this place offers
              </h3>
              <div className="w-8" />
            </div>

            {/* Modal Scrollable Content */}
            <div className="overflow-y-auto px-8 py-6 divide-y divide-[#EBEBEB] space-y-8">
              {amenityCategories.map((cat, idx) => (
                <div key={idx} className="pt-6 first:pt-0">
                  <h4 className="text-[18px] font-semibold text-[#222222] mb-4">
                    {cat.category}
                  </h4>
                  <div className="space-y-4">
                    {cat.items.map((item, itemIdx) => (
                      <div key={itemIdx} className="flex items-center gap-4">
                        <div className="shrink-0">{getAmenityIcon(item.name)}</div>
                        <span
                          className={`text-[15px] ${
                            item.unavailable
                              ? 'line-through text-[#717171]'
                              : 'text-[#222222]'
                          }`}
                        >
                          {item.name}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
