'use client';

import React from 'react';

interface CompactBarProps {
  isVisible?: boolean;
  activeSection?: string;
  onSectionClick?: (sectionId: string) => void;
  pricing?: {
    formattedTotalPrice?: string;
    nights?: number;
  };
  rating?: number;
  reviewCount?: number;
  onReserve?: () => void;
}

export function CompactBar({
  isVisible = false,
  activeSection = 'photos',
  onSectionClick,
  pricing = { formattedTotalPrice: '₹28,499', nights: 5 },
  rating = 4.95,
  reviewCount = 19,
  onReserve,
}: CompactBarProps) {
  const tabs = [
    { id: 'photos', label: 'Photos' },
    { id: 'amenities', label: 'Amenities' },
    { id: 'reviews', label: 'Reviews' },
    { id: 'location', label: 'Location' },
  ];

  const handleTabClick = (id: string) => {
    if (onSectionClick) {
      onSectionClick(id);
    } else {
      const el = document.getElementById(id);
      if (el) {
        const top = el.getBoundingClientRect().top + window.pageYOffset - 90;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    }
  };

  return (
    <nav
      aria-label="Listing section navigation"
      className={`fixed top-0 left-0 right-0 z-50 bg-white transition-all duration-300 font-cereal ${
        isVisible
          ? 'translate-y-0 opacity-100 shadow-[0_2px_4px_rgba(0,0,0,0.06)]'
          : '-translate-y-full opacity-0 pointer-events-none'
      }`}
    >
      <div className="max-w-[1400px] mx-auto px-40 h-[65px] flex items-center justify-between">
        {/* Navigation tabs */}
        <div className="flex items-center gap-6">
          {tabs.map((tab) => {
            const isActive = activeSection === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => handleTabClick(tab.id)}
                className={`relative pb-1 pt-1 text-[14px] font-medium cursor-pointer transition-colors focus:outline-none ${
                  isActive
                    ? 'text-black font-semibold border-b-2 border-black'
                    : 'text-[#222222] border-b-2 border-transparent hover:text-black'
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* Price, rating, and Reserve CTA */}
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end">
            <div className="flex items-baseline gap-1">
              <span className="text-[15px] font-medium text-[#222222]">
                {pricing.formattedTotalPrice}
              </span>
              <span className="text-[14px] text-[#222222] font-normal">
                for {pricing.nights} nights
              </span>
            </div>
            <div className="flex items-center gap-1 text-[13.8px] text-[#222222]">
              <span>★</span>
              <span>{typeof rating === 'number' ? rating.toFixed(2) : rating}</span>
              <span className="text-[#222222] font-normal">·</span>
              <span
                className="text-[#222222] font-normal cursor-pointer hover:underline"
                onClick={() => handleTabClick('reviews')}
              >
                {reviewCount} reviews
              </span>
            </div>
          </div>

          <button
            type="button"
            onClick={onReserve}
            className="bg-[#FF385C] hover:bg-[#E00B41] text-white font-medium px-6 py-3 rounded-lg text-[14px] cursor-pointer transition-all active:scale-95"
          >
            Reserve
          </button>
        </div>
      </div>
    </nav>
  );
}
