'use client';

import React from 'react';
import { listingData } from '../../constants/listing-data';

interface PropertySummaryProps {
  propertyType?: string;
  subtitle?: string;
  tagline?: string;
  rating?: number;
  reviewCount?: number;
}

export function PropertySummary({
  propertyType = listingData.propertyType,
  subtitle = listingData.stats.subtitle,
  tagline = listingData.guestFavorite.tagline,
  rating = listingData.guestFavorite.rating,
  reviewCount = listingData.guestFavorite.reviewCount,
}: PropertySummaryProps) {
  const scrollToReviews = () => {
    document.getElementById('reviews')?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <div className="font-cereal">
      {/* Property Title & Subtitle */}
      <div className="pt-0 pb-1">
        <h2 className="text-[22px] font-medium text-[#222222] tracking-normal leading-[1.3]">
          {propertyType}
        </h2>
        <p className="text-[16px] text-[#222222] font-normal leading-[1.4] mt-1">
          {subtitle}
        </p>
      </div>

      {/* Guest Favourite Card */}
      <div className="border border-[#DDDDDD] rounded-2xl px-6 py-5 my-7 flex items-center justify-between select-none">
        <div className="flex items-center gap-4">
          <img
            src="/assets/laurel-left-tTZ2KVHg.png"
            alt="Guest favourite laurel"
            className="h-10 w-auto object-contain"
          />
          <div className="flex flex-col">
            <span className="text-[16px] font-medium text-[#222222] leading-tight">
              Guest favourite
            </span>
            <span className="text-[14px] text-[#717171] leading-tight mt-1 max-w-[280px]">
              {tagline}
            </span>
          </div>
        </div>

        <div className="flex items-center text-[#222222] text-center">
          <div className="flex flex-col items-center">
            <span className="text-[18px] font-medium leading-none">
              {Number(rating).toFixed(2)}
            </span>
            <div
              className="flex items-center gap-[3px] mt-1 text-[#222222]"
              aria-label="5 out of 5 stars"
            >
              {[...Array(5)].map((_, idx) => (
                <div key={idx} className="w-[10px] h-[10px]">
                  <svg
                    viewBox="0 0 32 32"
                    aria-hidden="true"
                    role="presentation"
                    focusable="false"
                    style={{ display: 'block', height: '100%', width: '100%', fill: 'currentColor' }}
                  >
                    <path
                      fillRule="evenodd"
                      d="m15.1 1.58-4.13 8.88-9.86 1.27a1 1 0 0 0-.54 1.74l7.3 6.57-1.97 9.85a1 1 0 0 0 1.48 1.06l8.62-5 8.63 5a1 1 0 0 0 1.48-1.06l-1.97-9.85 7.3-6.57a1 1 0 0 0-.55-1.73l-9.86-1.28-4.12-8.88a1 1 0 0 0-1.82 0z"
                    />
                  </svg>
                </div>
              ))}
            </div>
          </div>

          <div className="w-px h-8 bg-[#DDDDDD] mx-5" aria-hidden="true" />

          <div
            className="flex flex-col items-center cursor-pointer"
            onClick={scrollToReviews}
          >
            <span className="text-[18px] font-medium leading-none underline">
              {reviewCount}
            </span>
            <span className="text-[12px] underline text-[#222222] font-normal leading-none mt-1">
              Reviews
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
