'use client';

import React, { useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

export function CalendarSection() {
  const weekdays = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];

  // October 2026 calendar data (starts on Thursday, 31 days)
  // Selected dates: 18 Oct to 23 Oct
  const [selectedStart, setSelectedStart] = useState<number | null>(18);
  const [selectedEnd, setSelectedEnd] = useState<number | null>(23);

  const octDays = Array.from({ length: 31 }, (_, i) => i + 1);
  const octStartOffset = 4; // Thursday

  const novDays = Array.from({ length: 30 }, (_, i) => i + 1);
  const novStartOffset = 0; // Sunday

  const handleClear = () => {
    setSelectedStart(null);
    setSelectedEnd(null);
  };

  const isSelected = (day: number) => {
    if (!selectedStart) return false;
    if (day === selectedStart || day === selectedEnd) return 'bound';
    if (selectedEnd && day > selectedStart && day < selectedEnd) return 'between';
    return false;
  };

  return (
    <div id="calendar" className="py-6 font-cereal">
      <div className="mb-6">
        <h2 className="text-[22px] font-medium text-[#222222]">
          5 nights in Candolim
        </h2>
        <p className="text-[14px] text-[#717171] mt-1">
          18 Oct 2026 – 23 Oct 2026
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 max-w-[650px]">
        {/* October 2026 */}
        <div>
          <div className="text-center font-semibold text-[16px] text-[#222222] mb-4">
            October 2026
          </div>
          <div className="grid grid-cols-7 text-center text-[12px] font-medium text-[#717171] mb-2">
            {weekdays.map((w, idx) => (
              <div key={idx} className="h-8 flex items-center justify-center">
                {w}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7 text-center text-[14px] font-medium">
            {[...Array(octStartOffset)].map((_, i) => (
              <div key={`empty-${i}`} className="h-10" />
            ))}
            {octDays.map((day) => {
              const status = isSelected(day);
              return (
                <div
                  key={day}
                  className={`h-10 flex items-center justify-center cursor-pointer relative ${
                    status === 'between' ? 'bg-[#F7F7F7]' : ''
                  }`}
                  onClick={() => {
                    if (!selectedStart || (selectedStart && selectedEnd)) {
                      setSelectedStart(day);
                      setSelectedEnd(null);
                    } else if (day > selectedStart) {
                      setSelectedEnd(day);
                    } else {
                      setSelectedStart(day);
                    }
                  }}
                >
                  <span
                    className={`w-9 h-9 flex items-center justify-center rounded-full transition ${
                      status === 'bound'
                        ? 'bg-[#222222] text-white font-semibold'
                        : 'text-[#222222] hover:border hover:border-black'
                    }`}
                  >
                    {day}
                  </span>
                </div>
              );
            })}
          </div>
        </div>

        {/* November 2026 */}
        <div>
          <div className="text-center font-semibold text-[16px] text-[#222222] mb-4">
            November 2026
          </div>
          <div className="grid grid-cols-7 text-center text-[12px] font-medium text-[#717171] mb-2">
            {weekdays.map((w, idx) => (
              <div key={idx} className="h-8 flex items-center justify-center">
                {w}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7 text-center text-[14px] font-medium">
            {[...Array(novStartOffset)].map((_, i) => (
              <div key={`empty-${i}`} className="h-10" />
            ))}
            {novDays.map((day) => (
              <div
                key={day}
                className="h-10 flex items-center justify-center cursor-pointer hover:bg-[#F7F7F7] rounded-full"
              >
                <span className="w-9 h-9 flex items-center justify-center rounded-full text-[#222222]">
                  {day}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="flex justify-end mt-4">
        <button
          type="button"
          onClick={handleClear}
          className="text-[14px] font-semibold underline text-[#222222] hover:text-black cursor-pointer focus:outline-none"
        >
          Clear dates
        </button>
      </div>

      <div className="w-full h-px bg-[#DDDDDD] my-6" />
    </div>
  );
}
