'use client';

import React, { useState } from 'react';
import { GuestFavouriteCenter } from './GuestFavouriteCenter';
import { RatingBars, RatingCategoryItem, RatingDistributionItem } from './RatingBars';
import { KeywordTags, KeywordTag } from './KeywordTags';
import { ReviewCard, ReviewItem } from './ReviewCard';
import { reviewsData } from '../../constants/listing-data';

export interface ReviewsDataProps {
  overallRating?: number;
  reviewCount?: number;
  guestFavouriteTagline?: string;
  ratingDistribution?: RatingDistributionItem[];
  categories?: RatingCategoryItem[];
  keywordTags?: KeywordTag[];
  items?: ReviewItem[];
}

interface ReviewsSectionProps {
  reviews?: ReviewsDataProps;
  onShowAll?: () => void;
}

export function ReviewsSection({
  reviews = reviewsData as unknown as ReviewsDataProps,
  onShowAll,
}: ReviewsSectionProps) {
  const [selectedTag, setSelectedTag] = useState<string | null>(null);

  const {
    overallRating = 4.95,
    reviewCount = 19,
    guestFavouriteTagline = 'This home is a guest favourite based on ratings, reviews and reliability',
    ratingDistribution = reviewsData.ratingDistribution,
    categories = reviewsData.categories,
    keywordTags = reviewsData.keywordTags,
    items = reviewsData.items as unknown as ReviewItem[],
  } = reviews || {};

  const filteredReviews = selectedTag
    ? items.filter((r) => r.tags && r.tags.includes(selectedTag))
    : items.slice(0, 6);

  return (
    <section id="reviews" className="w-full py-8 scroll-mt-24 font-cereal">
      {/* Center 3D Laurel Wreath Guest Favourite */}
      <GuestFavouriteCenter
        rating={overallRating}
        tagline={guestFavouriteTagline}
      />

      {/* 7-Column Rating Bars Breakdown with authentic SVGs */}
      <RatingBars
        ratingDistribution={ratingDistribution}
        categories={categories}
      />

      {/* Keyword tag filter pills */}
      <KeywordTags
        tags={keywordTags}
        selectedTag={selectedTag}
        onSelectTag={setSelectedTag}
      />

      {/* 2-Column Review Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-x-20 gap-y-10 mt-6 mb-10">
        {filteredReviews.map((review) => (
          <ReviewCard key={review.id} review={review} />
        ))}
      </div>

      {/* Show all reviews button */}
      <div className="pt-2">
        <button
          type="button"
          onClick={onShowAll}
          className="border border-[#222222] hover:bg-gray-100 active:scale-[0.99] text-[#222222] font-medium text-[16px] px-6 py-3.5 rounded-lg transition-all cursor-pointer focus:outline-none"
        >
          Show all {reviewCount} reviews
        </button>
      </div>
    </section>
  );
}
