'use client';

import React from 'react';
import { LayoutGrid } from 'lucide-react';
import { photoCategories } from '../../constants/listing-data';

interface PhotoGridProps {
  onPhotoClick?: (categoryId?: string, photoSrc?: string) => void;
  onShowAll?: () => void;
}

export function PhotoGrid({ onPhotoClick, onShowAll }: PhotoGridProps) {
  const categories = photoCategories;
  if (!categories || categories.length < 5) return null;

  const heroImage = categories[0].coverImage;
  const img1 = '/assets/living-room-2-3-D6DP_NhK.jpeg';
  const img2 = '/assets/living-room-2-2-kXn5mfy1.jpeg';
  const img3 = '/assets/bedroom5-CkhgeWg2.jpeg';
  const img4 = categories[4].coverImage;

  const handleOpen = (catId?: string, src?: string) => {
    if (onPhotoClick) {
      onPhotoClick(catId, src);
    } else if (onShowAll) {
      onShowAll();
    }
  };

  return (
    <div className="relative rounded-xl overflow-hidden flex h-[500px] gap-2 mt-6 font-cereal select-none">
      {/* Large Hero Left */}
      <div
        className="w-1/2 h-full cursor-pointer overflow-hidden group relative"
        onClick={() => handleOpen(categories[0].id, heroImage)}
      >
        <img
          src={heroImage}
          alt={categories[0].title}
          className="w-full h-full object-cover transition-transform duration-300"
        />
        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-all duration-300 pointer-events-none" />
      </div>

      {/* 2x2 Grid Right */}
      <div className="w-1/2 h-full flex flex-col gap-2">
        <div className="flex gap-2 h-[calc(50%-4px)]">
          <div
            className="w-1/2 h-full cursor-pointer overflow-hidden group relative"
            onClick={() => handleOpen('living-room-2', img1)}
          >
            <img
              src={img1}
              alt="Living room"
              className="w-full h-full object-cover transition-transform duration-300"
            />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-all duration-300 pointer-events-none" />
          </div>

          <div
            className="w-1/2 h-full cursor-pointer overflow-hidden group relative"
            onClick={() => handleOpen('living-room-2', img2)}
          >
            <img
              src={img2}
              alt="Living room"
              className="w-full h-full object-cover transition-transform duration-300"
            />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-all duration-300 pointer-events-none" />
          </div>
        </div>

        <div className="flex gap-2 h-[calc(50%-4px)]">
          <div
            className="w-1/2 h-full cursor-pointer overflow-hidden group relative"
            onClick={() => handleOpen('bedroom', img3)}
          >
            <img
              src={img3}
              alt="Bedroom"
              className="w-full h-full object-cover transition-transform duration-300"
            />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-all duration-300 pointer-events-none" />
          </div>

          <div
            className="w-1/2 h-full cursor-pointer overflow-hidden group relative"
            onClick={() => handleOpen(categories[4].id, img4)}
          >
            <img
              src={img4}
              alt={categories[4].title}
              className="w-full h-full object-cover transition-transform duration-300"
            />
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/10 transition-all duration-300 pointer-events-none" />
          </div>
        </div>
      </div>

      {/* Show all photos button */}
      <button
        type="button"
        onClick={() => (onShowAll ? onShowAll() : handleOpen())}
        className="absolute bottom-6 right-6 bg-white border border-black text-[#222222] font-semibold text-[14px] px-4 py-[6px] rounded-lg flex items-center gap-2 transition-colors shadow-sm cursor-pointer hover:bg-neutral-50 active:scale-95"
      >
        <LayoutGrid size={16} />
        Show all photos
      </button>
    </div>
  );
}
